import itertools

N = 189
representable = set()

# We check all combinations of a >= 0 and b >= 0 such that 11a + 20b <= N
for a in range(N // 11 + 1):
    for b in range(N // 20 + 1):
        n = 11 * a + 20 * b
        if n > 0:
            representable.add(n)

# We count how many numbers k in {1, 2, ..., 189} are NOT in the representable set.
# Since 0 is representable (a=0, b=0) but we only care about positive non-representable numbers.
non_representable_count = 0
for k in range(1, N + 1):
    if k not in representable:
        non_representable_count += 1

print(non_representable_count)

